package com.internetter.overheadscalecolor;

import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.MAGIC;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.MELEE;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.NO_RING;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.RANGED;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.ringSlotFor;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.HeadIcon;
import org.junit.Test;

/**
 * Pins the HeadIcon -> ring mapping.
 *
 * Worth a test because a mistake here is invisible: a wrongly-ringed overhead still looks like a
 * perfectly plausible plugin, so nothing about it draws attention. The rule is that only the three
 * protection prayers and their Deflect equivalents are ringed, and everything else renders ringless
 * rather than being assigned an invented color.
 */
public class RingSlotTest
{
	@Test
	public void protectionPrayersAndTheirDeflectEquivalentsShareASlot()
	{
		assertEquals(MELEE, ringSlotFor(HeadIcon.MELEE));
		assertEquals(MELEE, ringSlotFor(HeadIcon.DEFLECT_MELEE));

		assertEquals(RANGED, ringSlotFor(HeadIcon.RANGED));
		assertEquals(RANGED, ringSlotFor(HeadIcon.DEFLECT_RANGE));

		assertEquals(MAGIC, ringSlotFor(HeadIcon.MAGIC));
		assertEquals(MAGIC, ringSlotFor(HeadIcon.DEFLECT_MAGE));
	}

	@Test
	public void combinedAndNonProtectionOverheadsGetNoRing()
	{
		final Set<HeadIcon> ringless = EnumSet.of(
			// Combined overheads: no single correct color.
			HeadIcon.RANGE_MAGE,
			HeadIcon.RANGE_MELEE,
			HeadIcon.MAGE_MELEE,
			HeadIcon.RANGE_MAGE_MELEE,
			// Not protection prayers at all.
			HeadIcon.SMITE,
			HeadIcon.RETRIBUTION,
			HeadIcon.REDEMPTION,
			HeadIcon.WRATH,
			HeadIcon.SOUL_SPLIT);

		for (HeadIcon icon : ringless)
		{
			assertEquals("expected no ring for " + icon, NO_RING, ringSlotFor(icon));
		}
	}

	/**
	 * Guards against a new HeadIcon appearing in a future API version and silently falling into the
	 * default branch unnoticed. If this fails, decide deliberately whether the new icon is ringed.
	 */
	@Test
	public void everyHeadIconIsAccountedFor()
	{
		assertEquals("HeadIcon gained or lost values; revisit the ring mapping",
			15, HeadIcon.values().length);

		for (HeadIcon icon : HeadIcon.values())
		{
			final int slot = ringSlotFor(icon);
			assertNotNull(icon.name(), icon);
			if (slot != NO_RING && (slot < MELEE || slot > MAGIC))
			{
				throw new AssertionError("slot out of range for " + icon + ": " + slot);
			}
		}
	}
}

package com.internetter.overheadscalecolor;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadScaleColorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadScaleColorPlugin.class);
		RuneLite.main(args);
	}
}

package com.internetter.overheadscalecolor;

import java.awt.Color;

/**
 * Ring colour presets, including palettes chosen for the common forms of colour vision
 * deficiency (CVD).
 *
 * Why presets rather than "just shift the green a bit": a dichromat's colour space is effectively
 * two-dimensional -- one surviving hue axis plus luminance. Three categories separated only by hue
 * cannot be made reliable by nudging the shades. Each palette below therefore separates the three
 * prayer types on BOTH the surviving hue axis and luminance, and avoids the confusable pair
 * entirely rather than trying to fine-tune it.
 *
 * Colours are drawn from the Okabe-Ito qualitative palette where possible, which is the
 * long-standing reference set for CVD-safe categorical encoding.
 *
 * For anyone whose vision is not served by any of these, {@link #CUSTOM} hands all three colours
 * back to the user, and the "distinct ring styles" option adds a non-colour cue on top.
 */
public enum RingPalette
{
	/**
	 * Standard palette. Intuitive mapping, but red/green is precisely the pair lost in the most
	 * common deficiencies, so it is not a safe default for everyone.
	 */
	STANDARD("Standard", 0xFF4136, 0x2ECC40, 0x2E9BFF),

	/**
	 * Deuteranopia / deuteranomaly and protanopia / protanomaly -- red-green deficiency, by far the
	 * most common form (roughly 8% of men, 0.5% of women). Green is dropped entirely. Separation is
	 * orange (mid luminance, yellow axis) / white (max luminance, no hue) / blue (low luminance,
	 * blue axis), which survives both deutan and protan simulation.
	 */
	RED_GREEN("Red-green safe", 0xE69F00, 0xFFFFFF, 0x0072B2),

	/**
	 * Tritanopia / tritanomaly -- blue-yellow deficiency. Rare. Here red and green are reliable but
	 * blue/green and yellow/violet converge, so blue is dropped and magic moves to magenta.
	 */
	BLUE_YELLOW("Blue-yellow safe", 0xD55E00, 0x009E73, 0xCC79A7),

	/**
	 * Achromatopsia / monochromacy, and anyone who simply wants maximum contrast. Pure luminance
	 * separation. Enable "distinct ring styles" alongside this -- with no hue at all, the dash
	 * pattern is doing most of the work.
	 */
	MONOCHROME("Monochrome", 0xFFFFFF, 0xA0A0A0, 0x4A4A4A),

	/** Use the three colour pickers below instead of a preset. */
	CUSTOM("Custom", 0, 0, 0);

	private final String label;
	private final Color melee;
	private final Color ranged;
	private final Color magic;

	RingPalette(String label, int melee, int ranged, int magic)
	{
		this.label = label;
		this.melee = new Color(melee);
		this.ranged = new Color(ranged);
		this.magic = new Color(magic);
	}

	Color melee()
	{
		return melee;
	}

	Color ranged()
	{
		return ranged;
	}

	Color magic()
	{
		return magic;
	}

	/** RuneLite renders enum config items using toString(). */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.internetter.overheadscalecolor;

/**
 * How the plugin treats the client's own overhead icon.
 *
 * The distinction exists because of a hard client limitation. Drawing a resized icon requires the
 * client to stop drawing its own, and the only mechanism for that suppresses the player's entire 2D
 * pass -- icon, healthbar, hitsplats, overhead chat and name together. There is no way to suppress
 * the icon alone: {@code Player} has no overhead-icon setter, {@code Client} has no hide flags, and
 * sprite overrides do not reach overhead icons (tested in game, they do not).
 *
 * The ring, by contrast, is drawn by an overlay on top of the scene and needs nothing suppressed.
 * So colouring costs nothing and resizing costs the 2D pass, and the two are separated here rather
 * than bundled.
 */
public enum OverheadMode
{
	/**
	 * Hide the client's icon and show only the coloured ring. The ring itself is the indicator of
	 * which protection prayer is active, so nothing needs to line up with anything.
	 */
	RING_ONLY("Ring only"),

	/** Hide the client's icon and draw a resized copy of it, with the ring around it. */
	SHRINK("Shrink icon");

	private final String label;

	OverheadMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.internetter.overheadscalecolor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.awt.Font;
import java.awt.GradientPaint;
import java.awt.FontMetrics;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.HealthBarConfig;
import net.runelite.api.HeadIcon;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the overhead indicator -- the ring, and in Shrink mode a resized icon -- plus the 2D
 * elements that hiding the client's icon takes with it.
 *
 * Icons come from sprite archive {@link SpriteID#HEADICONS_PRAYER} (440), indexed by
 * {@link HeadIcon#ordinal()}. That correspondence is inferred rather than documented, though icons
 * render correctly in game.
 *
 * The icon and ring path allocates nothing: images, colors and strokes are memoised and rebuilt
 * only on config change. Restored hitsplats allocate one GradientPaint per visible splat, bounded
 * at four and only while splats are on screen.
 */
@Slf4j
public class OverheadScaleColorOverlay extends Overlay
{
	/** Ring outline. Softened black -- pure black reads as a hard edge at 1px. */
	private static final Color RING_OUTLINE = new Color(0, 0, 0, 180);

	private static final Color HITSPLAT_OUTLINE = new Color(0, 0, 0, 180);
	private static final Stroke HITSPLAT_STROKE = new BasicStroke(1f);

	/** Reused each frame rather than allocated per splat. */
	private final Path2D.Double starPath = new Path2D.Double();
	private final RestoredHitsplat[] liveSplats = new RestoredHitsplat[4];
	private Font hitsplatFont;

	/** Ring slots. Also index the color and stroke arrays. */
	static final int MELEE = 0;
	static final int RANGED = 1;
	static final int MAGIC = 2;
	static final int NO_RING = -1;

	/** Offsets skull entries away from HeadIcon ordinals in the shared sprite caches. */
	private static final int SKULL_CACHE_NS = 1000;

	private final Client client;
	private final OverheadScaleColorConfig config;
	private final SpriteManager spriteManager;

	/** Scaled images, memoised per (icon ordinal, scale, interpolation). */
	private final Map<Long, BufferedImage> scaledCache = new HashMap<>();

	/** Native (unscaled) sprites, memoised per icon ordinal. Never holds null -- see below. */
	private final Map<Integer, BufferedImage> nativeCache = new HashMap<>();

	private final Color[] ringColors = new Color[3];
	private final Stroke[] ringStrokes = new Stroke[3];
	private final Stroke[] outlineStrokes = new Stroke[3];
	private boolean ringStateValid;

	/** Bitmask of icon ordinals already logged as missing, so the log is not written per frame. */
	private int missingLogged;

	/**
	 * The client's own health bar definition, captured from PostHealthBarConfig. Suppressing the 2D
	 * pass takes the real bar with it, so in Shrink mode we redraw one using these exact sprites.
	 * Volatile because the event arrives off the client thread.
	 */
	private volatile HealthBarConfig healthBarConfig;
	private BufferedImage healthBarFront;
	private BufferedImage healthBarBack;
	private HealthBarConfig healthBarCachedFrom;
	private boolean healthBarFallbackLogged;

	void setHealthBarConfig(HealthBarConfig cfg)
	{
		this.healthBarConfig = cfg;
	}

	/**
	 * Hitsplats recorded while suppression is hiding the client's own. Bounded at four, which is what
	 * the client itself shows at once. Written from the event thread, read on the client thread, so
	 * the deque is synchronised on itself at both ends.
	 */
	private final Deque<RestoredHitsplat> hitsplats = new ArrayDeque<>();

	void recordHitsplat(RestoredHitsplat splat)
	{
		synchronized (hitsplats)
		{
			while (hitsplats.size() >= 4)
			{
				hitsplats.pollFirst();
			}
			hitsplats.addLast(splat);
		}
	}

	@Inject
	OverheadScaleColorOverlay(Client client, OverheadScaleColorConfig config, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.spriteManager = spriteManager;
		// UNDER_WIDGETS, not ABOVE_SCENE, despite the names. ABOVE_SCENE is rendered from the
		// client's drawScene() hook, which runs BEFORE overheads and 2D entity elements are drawn --
		// so anything we drew there was painted over by the client a moment later, putting hitsplats
		// behind the player and the ring behind the prayer icon. UNDER_WIDGETS is rendered from
		// drawAboveOverheads(), which is after all of that but still beneath interfaces, which is
		// exactly where these belong.
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
	}

	/**
	 * Invalidation is requested from the AWT event thread (config changes and plugin lifecycle both
	 * arrive there) but the caches are read and written by {@link #render(Graphics2D)} on the client
	 * thread. Clearing them directly would be concurrent mutation of a plain HashMap, so these only
	 * raise a flag and the client thread does the actual clearing at the top of the next frame.
	 */
	private volatile boolean invalidatePending;
	private volatile boolean fullInvalidatePending;

	/** Config changed: drop derived state, keep the native sprites. */
	void invalidate()
	{
		invalidatePending = true;
	}

	/**
	 * Plugin stopping: drop everything. The plugin instance and this overlay survive a
	 * disable/enable cycle in RuneLite, so the sprites are dropped too rather than left to go stale.
	 */
	void invalidateAll()
	{
		fullInvalidatePending = true;
	}

	/** Must only be called on the client thread. */
	private void applyPendingInvalidation()
	{
		if (fullInvalidatePending)
		{
			fullInvalidatePending = false;
			invalidatePending = false;
			nativeCache.clear();
			scaledCache.clear();
			ringStateValid = false;
			missingLogged = 0;
		}
		else if (invalidatePending)
		{
			invalidatePending = false;
			scaledCache.clear();
			ringStateValid = false;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		applyPendingInvalidation();

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		final LocalPoint lp = local.getLocalLocation();
		if (lp == null)
		{
			return null;
		}

		final HeadIcon icon = local.getOverheadIcon();
		final boolean shrink = config.mode() == OverheadMode.SHRINK;

		// Both modes hide the client's icon, so both owe it the rest of the 2D pass back. This is not
		// the same condition as "an overhead icon is showing".
		final boolean suppressing = !config.hideOnlyWhilePraying() || icon != null;

		if (icon != null)
		{
			drawIcon(graphics, local, lp, icon, shrink);
		}

		if (suppressing)
		{
			if (config.restoreHealthBar())
			{
				drawHealthBar(graphics, local, lp);
			}

			if (config.restoreHitsplats())
			{
				drawHitsplats(graphics, local, lp);
			}

			if (config.restoreSkull())
			{
				drawSkull(graphics, local, lp);
			}

			if (config.restoreOverheadChat())
			{
				drawOverheadChat(graphics, local, lp);
			}
		}

		return null;
	}

	private void drawIcon(Graphics2D graphics, Player local, LocalPoint lp, HeadIcon icon, boolean shrink)
	{
		final BufferedImage nativeImg = nativeSprite(icon);
		if (nativeImg == null)
		{
			return;
		}

		final int zOffset = local.getLogicalHeight() + config.heightOffset();

		if (!shrink)
		{
			// Ring-only: no icon is drawn, so the ring is sized straight from Scale % rather than
			// from a sprite, and centred on the projected point.
			final Point centre = Perspective.localToCanvas(client, lp,
				client.getTopLevelWorldView().getPlane(), zOffset);
			if (centre == null || !config.ringEnabled())
			{
				return;
			}

			final int base = Math.max(1, nativeImg.getWidth() * config.scale() / 100);
			drawRingAt(graphics, icon, centre.getX(), centre.getY(), base / 2 + config.ringGap());
			return;
		}

		final BufferedImage img = scaled(icon.ordinal(), nativeImg, config.scale(), config.smoothScaling());

		final Point p = Perspective.getCanvasImageLocation(client, lp, img, zOffset);
		if (p == null)
		{
			return;
		}

		final int x = p.getX();
		final int y = p.getY() + (nativeImg.getHeight() - img.getHeight()) / 2;

		if (config.ringEnabled())
		{
			drawRing(graphics, icon, x, y, img.getWidth(), img.getHeight());
		}

		graphics.drawImage(img, x, y, null);
	}

	/**
	 * Puts back the PK skull that suppression removed. Scaled alongside the prayer icon so the two
	 * stay visually consistent.
	 */
	private void drawSkull(Graphics2D graphics, Player local, LocalPoint lp)
	{
		final int skull = local.getSkullIcon();
		if (skull < 0)
		{
			return;
		}

		final BufferedImage nativeImg = skullSprite(skull);
		if (nativeImg == null)
		{
			return;
		}

		final BufferedImage img = scaled(SKULL_CACHE_NS + skull, nativeImg, config.scale(), config.smoothScaling());

		final Point p = Perspective.getCanvasImageLocation(client, lp, img,
			local.getLogicalHeight() + config.skullOffset());
		if (p == null)
		{
			return;
		}

		graphics.drawImage(img, p.getX(), p.getY() + (nativeImg.getHeight() - img.getHeight()) / 2, null);
	}

	/**
	 * Puts back the overhead chat text that suppression removed.
	 *
	 * Drawn in the game's own font via FontManager, so the typeface matches rather than approximates.
	 * The client keeps ticking getOverheadText() down regardless of whether it is drawn, so the text
	 * clears itself on the client's schedule and needs no timer here.
	 *
	 * Not reproduced: chat effects (wave, scroll, flashing colours). Those are cache-driven and not
	 * exposed, so effect text renders as plain text.
	 */
	private void drawOverheadChat(Graphics2D graphics, Player local, LocalPoint lp)
	{
		final String text = local.getOverheadText();
		if (text == null || text.isEmpty())
		{
			return;
		}

		final Font priorFont = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeFont());

		final Point p = Perspective.getCanvasTextLocation(client, graphics, lp, text,
			local.getLogicalHeight() + config.chatOffset());

		if (p != null)
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, p.getX() + 1, p.getY() + 1);
			graphics.setColor(config.chatColor());
			graphics.drawString(text, p.getX(), p.getY());
		}

		graphics.setFont(priorFont);
	}

	private BufferedImage skullSprite(int index)
	{
		final int key = SKULL_CACHE_NS + index;
		final BufferedImage cached = nativeCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		final BufferedImage img = spriteManager.getSprite(SpriteID.HEADICONS_PK, index);
		if (img != null)
		{
			nativeCache.put(key, img);
		}
		return img;
	}

	/**
	 * The ring is stroked at render time rather than baked into the cached image deliberately. Its
	 * whole purpose is legibility at small scales, and baking it in would shrink it along with the
	 * icon -- thinnest exactly when it matters most. Thickness is in screen pixels instead.
	 */
	private void drawRing(Graphics2D graphics, HeadIcon icon, int x, int y, int w, int h)
	{
		drawRingAt(graphics, icon, x + w / 2, y + h / 2, Math.max(w, h) / 2 + config.ringGap());
	}

	private void drawRingAt(Graphics2D graphics, HeadIcon icon, int cx, int cy, int radius)
	{
		final int slot = ringSlotFor(icon);
		if (slot < 0)
		{
			return;
		}

		if (!ringStateValid)
		{
			refreshRingState();
		}

		final int diameter = radius * 2;
		final int left = cx - radius;
		final int top = cy - radius;

		final Object priorAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Stroke priorStroke = graphics.getStroke();

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (config.ringOutline())
		{
			graphics.setStroke(outlineStrokes[slot]);
			graphics.setColor(RING_OUTLINE);
			graphics.drawOval(left, top, diameter, diameter);
		}

		graphics.setStroke(ringStrokes[slot]);
		graphics.setColor(ringColors[slot]);
		graphics.drawOval(left, top, diameter, diameter);

		graphics.setStroke(priorStroke);
		if (priorAA != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, priorAA);
		}
	}

	/**
	 * Resolve palette colors and build strokes once per config change. Reading a Color back from
	 * ConfigManager parses a string and allocates, so doing this per frame would allocate on every
	 * render.
	 */
	private void refreshRingState()
	{
		final RingPalette palette = config.palette();
		if (palette == RingPalette.CUSTOM)
		{
			ringColors[MELEE] = config.meleeColor();
			ringColors[RANGED] = config.rangedColor();
			ringColors[MAGIC] = config.magicColor();
		}
		else
		{
			ringColors[MELEE] = palette.melee();
			ringColors[RANGED] = palette.ranged();
			ringColors[MAGIC] = palette.magic();
		}

		final float thickness = config.ringThickness();
		final float outline = thickness + 2f;

		if (config.distinctStyles())
		{
			// A cue that survives total color loss: melee solid, ranged dashed, magic dotted.
			// Dash lengths scale with thickness so the pattern stays legible as it thickens.
			final float[] dashed = {thickness * 2.5f, thickness * 2f};
			final float[] dotted = {0.1f, thickness * 2.6f};

			ringStrokes[MELEE] = new BasicStroke(thickness);
			ringStrokes[RANGED] = new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, dashed, 0f);
			ringStrokes[MAGIC] = new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, dotted, 0f);

			// The outline follows the same dash pattern; a solid dark ring underneath would swamp
			// the shape cue this option exists to provide.
			outlineStrokes[MELEE] = new BasicStroke(outline);
			outlineStrokes[RANGED] = new BasicStroke(outline, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, dashed, 0f);
			outlineStrokes[MAGIC] = new BasicStroke(outline, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, dotted, 0f);
		}
		else
		{
			final Stroke ring = new BasicStroke(thickness);
			final Stroke out = new BasicStroke(outline);
			for (int i = 0; i < 3; i++)
			{
				ringStrokes[i] = ring;
				outlineStrokes[i] = out;
			}
		}

		ringStateValid = true;
	}

	/**
	 * Which ring slot an icon uses, or -1 for icons that render ringless.
	 *
	 * Deflect variants share their protection-prayer equivalent's slot. Combined overheads and the
	 * non-protection prayers (Smite, Retribution, Redemption, Wrath, Soul Split) get no ring rather
	 * than an invented color.
	 */
	static int ringSlotFor(HeadIcon icon)
	{
		switch (icon)
		{
			case MELEE:
			case DEFLECT_MELEE:
				return MELEE;
			case RANGED:
			case DEFLECT_RANGE:
				return RANGED;
			case MAGIC:
			case DEFLECT_MAGE:
				return MAGIC;
			default:
				return NO_RING;
		}
	}

	/**
	 * Redraws the health bar the 2D suppression removed, using the client's own sprites so it is
	 * indistinguishable from vanilla.
	 *
	 * getHealthRatio() returns -1 when the client would not be showing a bar at all, so the timing
	 * comes from the client rather than being guessed -- the bar appears and disappears exactly when
	 * it normally would.
	 */
	private void drawHealthBar(Graphics2D graphics, Player local, LocalPoint lp)
	{
		final int ratio = local.getHealthRatio();
		final int scale = local.getHealthScale();
		if (ratio < 0 || scale <= 0)
		{
			return;
		}

		final HealthBarConfig cfg = healthBarConfig;
		if (cfg != null && cfg != healthBarCachedFrom)
		{
			healthBarCachedFrom = cfg;
			healthBarFront = spriteToImage(cfg.getHealthBarFrontSprite());
			healthBarBack = spriteToImage(cfg.getHealthBarBackSprite());
		}

		// PostHealthBarConfig fires when the client is about to draw a health bar -- which is the
		// very thing being vetoed. If suppression started before the client ever drew one, the event
		// never arrives and we have no sprites. Falling back to a drawn bar means a bar always shows;
		// it is swapped for the client's own sprites the moment the event does arrive.
		if (healthBarFront == null || healthBarBack == null)
		{
			if (!healthBarFallbackLogged)
			{
				healthBarFallbackLogged = true;
				log.debug("no health bar sprites yet, drawing fallback bar");
			}

			drawFallbackHealthBar(graphics, local, lp, ratio, scale);
			return;
		}

		final int w = healthBarFront.getWidth();
		final int h = healthBarFront.getHeight();

		final Point p = Perspective.getCanvasImageLocation(client, lp, healthBarFront,
			local.getLogicalHeight() + config.healthBarOffset());
		if (p == null)
		{
			return;
		}

		final int filled = Math.min(w, (int) Math.round((double) w * ratio / scale));

		graphics.drawImage(healthBarBack, p.getX(), p.getY(), null);
		if (filled > 0)
		{
			graphics.drawImage(healthBarFront, p.getX(), p.getY(), p.getX() + filled, p.getY() + h,
				0, 0, filled, h, null);
		}
	}

	/**
	 * Redraws the hitsplats suppression removed. Expiry uses the client's own
	 * getDisappearsOnGameCycle, so they last exactly as long as the real ones would.
	 */
	private void drawHitsplats(Graphics2D graphics, Player local, LocalPoint lp)
	{
		final int cycle = client.getGameCycle();

		final int count;
		synchronized (hitsplats)
		{
			final int linger = config.hitsplatLingerMs() / 20;
			hitsplats.removeIf(h -> h.expired(cycle - linger));
			if (hitsplats.isEmpty())
			{
				return;
			}

			int i = 0;
			for (RestoredHitsplat h : hitsplats)
			{
				liveSplats[i++] = h;
			}
			count = i;
		}

		final Point anchor = Perspective.localToCanvas(client, lp,
			client.getTopLevelWorldView().getPlane(),
			local.getLogicalHeight() + config.hitsplatOffset());
		if (anchor == null)
		{
			return;
		}

		final Object priorAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		final Font priorFont = graphics.getFont();
		if (hitsplatFont == null)
		{
			hitsplatFont = priorFont.deriveFont(Font.BOLD, 12f);
		}
		graphics.setFont(hitsplatFont);
		final FontMetrics fm = graphics.getFontMetrics();

		// Spread multiple splats horizontally, centred on the player, like the client does.
		final int w = config.hitsplatSize();
		final int h = (int) Math.round(w * 0.9);
		final int spacing = w - w / 5;
		int cx = anchor.getX() - ((count - 1) * spacing) / 2;

		final Stroke priorStroke = graphics.getStroke();
		graphics.setStroke(HITSPLAT_STROKE);

		for (int i = 0; i < count; i++)
		{
			final RestoredHitsplat splat = liveSplats[i];
			final int cy = anchor.getY();
			final Shape star = fourPointStar(cx, cy, w / 2.0, h / 2.0);

			// Shade top-to-bottom rather than filling flat, so the splat has the same sense of
			// volume the client's own graphics have.
			graphics.setPaint(new GradientPaint(
				cx, cy - h / 2f, splat.highlight,
				cx, cy + h / 2f, splat.shadow));
			graphics.fill(star);

			// setColor replaces the gradient paint for the outline.
			graphics.setColor(HITSPLAT_OUTLINE);
			graphics.draw(star);

			final String text = Integer.toString(splat.amount);
			final int tx = cx - fm.stringWidth(text) / 2;
			final int ty = cy + fm.getAscent() / 2 - 1;

			// A single drop shadow leaves the glyph edges blending into the fill behind them. A full
			// outline on all eight sides separates the number from the splat colour completely, so it
			// stays unambiguous on light fills like white and yellow as well as dark ones.
			graphics.setColor(Color.BLACK);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						graphics.drawString(text, tx + dx, ty + dy);
					}
				}
			}

			graphics.setColor(Color.WHITE);
			graphics.drawString(text, tx, ty);

			cx += spacing;
		}

		graphics.setStroke(priorStroke);

		graphics.setFont(priorFont);
		if (priorAA != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, priorAA);
		}
	}

	/**
	 * A four-point star with concave sides, matching the plugin's own icon. The waist factor sets how
	 * deeply the sides pinch: lower is spikier, higher is rounder. 0.26 keeps the centre wide enough
	 * for a three-digit number to sit legibly inside.
	 */
	private Shape fourPointStar(double cx, double cy, double rx, double ry)
	{
		final double waist = 0.26;
		final double wx = rx * waist;
		final double wy = ry * waist;

		final Path2D.Double p = starPath;
		p.reset();
		p.moveTo(cx, cy - ry);
		p.quadTo(cx + wx, cy - wy, cx + rx, cy);
		p.quadTo(cx + wx, cy + wy, cx, cy + ry);
		p.quadTo(cx - wx, cy + wy, cx - rx, cy);
		p.quadTo(cx - wx, cy - wy, cx, cy - ry);
		p.closePath();
		return p;
	}

	/**
	 * Health bar drawn from scratch, used only until the client's own sprites become available.
	 * Deliberately plain: green over red at the size of a default bar.
	 */
	private void drawFallbackHealthBar(Graphics2D graphics, Player local, LocalPoint lp, int ratio, int scale)
	{
		final int w = 30;
		final int h = 5;

		final Point centre = Perspective.localToCanvas(client, lp,
			client.getTopLevelWorldView().getPlane(),
			local.getLogicalHeight() + config.healthBarOffset());
		if (centre == null)
		{
			return;
		}

		final int x = centre.getX() - w / 2;
		final int y = centre.getY() - h / 2;
		final int filled = Math.max(0, Math.min(w, (int) Math.round((double) w * ratio / scale)));

		graphics.setColor(new Color(0x7F0000));
		graphics.fillRect(x, y, w, h);
		graphics.setColor(new Color(0x00B000));
		graphics.fillRect(x, y, filled, h);
		graphics.setColor(new Color(0, 0, 0, 190));
		graphics.drawRect(x, y, w, h);
	}

	private static BufferedImage spriteToImage(net.runelite.api.SpritePixels sprite)
	{
		try
		{
			return sprite == null ? null : sprite.toBufferedImage();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private BufferedImage nativeSprite(HeadIcon icon)
	{
		final int index = icon.ordinal();
		final BufferedImage cached = nativeCache.get(index);
		if (cached != null)
		{
			return cached;
		}

		final BufferedImage img = spriteManager.getSprite(SpriteID.HEADICONS_PRAYER, index);
		if (img == null)
		{
			// Deliberately NOT cached. getSprite returns null while the client's sprite cache is
			// still warming up, and caching that would permanently blank this icon for the rest of
			// the session. Retrying costs a map lookup per frame until it resolves.
			if ((missingLogged & (1 << index)) == 0)
			{
				missingLogged |= 1 << index;
				log.debug("no sprite yet for HeadIcon {} (archive {} index {})", icon, SpriteID.HEADICONS_PRAYER, index);
			}
			return null;
		}

		nativeCache.put(index, img);
		return img;
	}

	private BufferedImage scaled(int id, BufferedImage src, int scalePercent, boolean smooth)
	{
		final long key = ((long) id << 32) | ((long) scalePercent << 1) | (smooth ? 1 : 0);
		final BufferedImage cached = scaledCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		if (scalePercent == 100)
		{
			scaledCache.put(key, src);
			return src;
		}

		final int w = Math.max(1, src.getWidth() * scalePercent / 100);
		final int h = Math.max(1, src.getHeight() * scalePercent / 100);

		final BufferedImage dst = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = dst.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			smooth ? RenderingHints.VALUE_INTERPOLATION_BILINEAR : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();

		scaledCache.put(key, dst);
		return dst;
	}
}

package com.internetter.overheadscalecolor;

import java.awt.Color;
import net.runelite.api.HitsplatID;

/**
 * One hitsplat the 2D suppression removed, held until the client says it would have expired.
 *
 * Unlike the health bar, the client does not hand us its hitsplat graphics -- there is no equivalent
 * of PostHealthBarConfig, and the Hitmark sprite group is indexed by something other than the
 * hitsplat type. These are therefore drawn rather than reproduced. The colours below follow what
 * each type actually looks like in game, so a poison hit reads as poison and a max hit reads as a
 * max hit, but they are this plugin's rendition rather than the client's own pixels.
 */
final class RestoredHitsplat
{
	// Base colours, keyed to how each splat actually appears in game.
	private static final Color RED = new Color(0xB01818);        // ordinary damage
	private static final Color RED_MAX = new Color(0xE02020);    // max hit, brighter than ordinary
	private static final Color BLUE = new Color(0x2050B0);       // block / zero damage
	private static final Color GREEN = new Color(0x1E8C1E);      // poison
	private static final Color GREEN_DARK = new Color(0x0A4A0A); // venom
	private static final Color ORANGE_DISEASE = new Color(0xB86A18);
	private static final Color PURPLE = new Color(0x8A2BC0);     // heal
	private static final Color CYAN = new Color(0x18A0B0);
	private static final Color ORANGE = new Color(0xD07818);
	private static final Color YELLOW = new Color(0xC8B018);
	private static final Color WHITE = new Color(0xD8D8D8);
	private static final Color POISE = new Color(0x707890);
	private static final Color PRAYER = new Color(0x3858C0);
	private static final Color BLEED = new Color(0x8C1030);
	private static final Color SANITY_LOSS = new Color(0x6038A0);
	private static final Color SANITY_GAIN = new Color(0x38A0A0);
	private static final Color DOOM = new Color(0x582060);
	private static final Color BURN = new Color(0xC04810);
	private static final Color CORRUPTION = new Color(0x0E7A5A);

	final int amount;
	final int type;
	final int expiresOnCycle;

	/** Derived once here rather than per frame, since they depend only on the type. */
	final Color highlight;
	final Color shadow;

	RestoredHitsplat(int amount, int type, int expiresOnCycle)
	{
		this.amount = amount;
		this.type = type;
		this.expiresOnCycle = expiresOnCycle;

		final Color base = color();
		this.highlight = shift(base, 0.42f);
		this.shadow = shift(base, -0.30f);
	}

	boolean expired(int gameCycle)
	{
		return gameCycle >= expiresOnCycle;
	}

	Color color()
	{
		switch (type)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
				return BLUE;

			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
				return RED;

			case HitsplatID.DAMAGE_MAX_ME:
				return RED_MAX;

			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.CYAN_UP:
			case HitsplatID.CYAN_DOWN:
				return CYAN;

			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
				return ORANGE;

			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
				return YELLOW;

			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return WHITE;

			case HitsplatID.DAMAGE_ME_POISE:
			case HitsplatID.DAMAGE_OTHER_POISE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return POISE;

			case HitsplatID.POISON:
				return GREEN;
			case HitsplatID.VENOM:
				return GREEN_DARK;
			case HitsplatID.DISEASE:
			case HitsplatID.DISEASE_BLOCKED:
				return ORANGE_DISEASE;
			case HitsplatID.HEAL:
				return PURPLE;
			case HitsplatID.PRAYER_DRAIN:
				return PRAYER;
			case HitsplatID.BLEED:
				return BLEED;
			case HitsplatID.SANITY_DRAIN:
				return SANITY_LOSS;
			case HitsplatID.SANITY_RESTORE:
				return SANITY_GAIN;
			case HitsplatID.DOOM:
				return DOOM;
			case HitsplatID.BURN:
				return BURN;
			case HitsplatID.CORRUPTION:
				return CORRUPTION;

			default:
				// Unknown or newly added type: fall back on the damage/zero convention rather than
				// inventing a colour, so a future hitsplat still reads sensibly.
				return amount == 0 ? BLUE : RED;
		}
	}

	private static Color shift(Color c, float amount)
	{
		if (amount >= 0)
		{
			return new Color(
				(int) (c.getRed() + (255 - c.getRed()) * amount),
				(int) (c.getGreen() + (255 - c.getGreen()) * amount),
				(int) (c.getBlue() + (255 - c.getBlue()) * amount));
		}

		final float k = 1f + amount;
		return new Color((int) (c.getRed() * k), (int) (c.getGreen() * k), (int) (c.getBlue() * k));
	}
}

